R = json.load(open("results.json"))
P1 = R["part1"]; cm = P1["cm"]; T = R["tradeoffs"]; B5 = R["baseline_05"]; A = R["adv"]; D = A["demo"]; TR = A["traits"]
ovb = pd.DataFrame(R["ovb"]["table"]).set_index("predictor")
